import{apps,log,testimony,canUnlock}from'./story.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={clues:{},restored:false,history:[],phase:'exploration',hint:0,scar:false},windows=new Map(),z=10,folder='Desktop',photo=0,term=['SEN terminal / simulated environment','Type help for available commands.'],audioCtx,oscillators=[],soundOn=false;
const heading=(name,issue='PERSONAL ARCHIVE')=>`<div class="paper-head"><div class="issue"><span>${issue}</span><span>14 NOV · 02:13</span></div><h2>${name}</h2></div>`;
const wrap=(name,body,issue)=>heading(name,issue)+`<div class="article">${body}</div>`;
try{const saved=JSON.parse(localStorage.getItem("archive-case1"));if(saved?.clues&&saved?.history)state=saved;if(state.phase==="recovering")state.phase="exploration"}catch{}
function persist(){try{localStorage.setItem("archive-case1",JSON.stringify(state))}catch{}}
function record(action){state.history.push({action,time:'02:13',index:state.history.length+1});persist()}
function notify(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').hidden=true,6500)}
function clue(key,value){if(state.clues[key])return;state.clues[key]=value;record(`Recovered fragment ${key}: ${value}`);update();refresh('locked');notify(Object.keys(state.clues).length===2?'Recovered message · Mira: “If you can still read this, keep going. The summaries are wrong.”':`Memory fragment ${key} recovered. ${Object.keys(state.clues).length} of 3.`)}
function update(){persist();const n=Object.keys(state.clues).length;$('#fragments').textContent=['A','B','C'].map(k=>state.clues[k]?'●':'○').join(' ');$('#integrity').textContent=state.phase==='preserved'?'Witness record preserved.':`${n} / 3 fragments recovered`;$('#systemstatus').textContent=state.phase==='preserved'?'WITNESS RECORD PRESERVED':n===3?'MEMORY INCONSISTENCY CONFIRMED':n?'INCONSISTENCY DETECTED':'LOCAL SESSION / FICTIONAL DEMO';$('#osname').textContent=['reveal','preserved'].includes(state.phase)?'PALISADE / Reconstruction 09':'SEN PERSONAL SYSTEM';$('#desktop').classList.toggle('reconstructed',['reveal','preserved'].includes(state.phase));$('#desktop').classList.toggle('preserved',state.phase==='preserved');$('.desktop-icons').innerHTML=Object.entries(apps).map(([id,[symbol,title,cls]])=>`<button class="desktop-icon" data-open="${id}"><span class="icon ${cls}" aria-hidden="true">${symbol}</span><span>${id==='files'&&state.phase!=='exploration'?'Memory fragments':title}</span></button>`).join('');tasks()}
function tasks(){$('#tasks').innerHTML=[...windows].map(([id,w])=>`<button data-task="${id}" class="${w.hidden?'':'active'}">${apps[id]?.[0]||'≡'} ${id==='locked'?'Recovery':apps[id]?.[1]||id}</button>`).join('')}
function observe(w){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{root:w.querySelector('.window-body'),threshold:.12});w.querySelectorAll('.reveal-block').forEach(el=>io.observe(el))}
function refresh(id){const w=windows.get(id);if(w){w.querySelector('.window-body').innerHTML=content(id);observe(w)}}
function focusWin(w){w.style.zIndex=++z}
function open(id){record(`Opened ${id==='locked'?'IF_YOU_FOUND_THIS.locked':id}`);if(windows.has(id)){const w=windows.get(id);w.hidden=false;focusWin(w);tasks();w.querySelector('.titlebar button').focus();return}const w=document.createElement('section');w.className='window';w.dataset.app=id;w.setAttribute('aria-label',apps[id]?.[1]||id);const count=windows.size;w.style.left=`${Math.min(16+count*1.3,Math.max(1,innerWidth/16-44))}rem`;w.style.top=`${4.5+count%5*.9}rem`;w.innerHTML=`<div class="titlebar"><span>${apps[id]?.[0]||'≡'} &nbsp; ${esc(apps[id]?.[1]||id)} <span class="muted">/ recovered</span></span><div class="controls"><button data-win="min" aria-label="Minimize ${id}">−</button><button data-win="max" aria-label="Maximize or restore ${id}">□</button><button data-win="close" aria-label="Close ${id}">×</button></div></div><div class="window-body">${content(id)}</div>`;$('#windows').append(w);windows.set(id,w);focusWin(w);tasks();drag(w);observe(w);w.addEventListener('pointerdown',()=>focusWin(w));w.querySelector('.controls button').focus();if(id==='log')clue('C',9)}
function close(id){windows.get(id)?.remove();windows.delete(id);tasks();document.querySelector(`[data-open="${id}"]`)?.focus()}
function drag(w){const bar=w.querySelector('.titlebar');bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||innerWidth<701||w.classList.contains('maximized'))return;const rect=w.getBoundingClientRect(),dx=e.clientX-rect.left,dy=e.clientY-rect.top;bar.setPointerCapture(e.pointerId);bar.onpointermove=ev=>{w.style.left=`${Math.max(0,Math.min(innerWidth-rect.width,ev.clientX-dx))/16}rem`;w.style.top=`${Math.max(2.6*16,Math.min(innerHeight-6*16,ev.clientY-dy))/16}rem`};bar.onpointerup=()=>bar.onpointermove=null;bar.onpointercancel=()=>bar.onpointermove=null})}
function scene(n){if(n===0)return `<svg class="photo" role="img" aria-label="An empty Kolkata station platform with exactly three unmistakable yellow seats" viewBox="0 0 640 330" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#203c45"/><stop offset="1" stop-color="#84958a"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h640v330H0z"/><path fill="#183234" d="M0 40h640v24H0zM30 0h10v250H30zM570 0h12v250h-12z"/><path fill="#a1a38b" d="M0 210h640v120H0z"/><path fill="#2f4441" d="M0 280h640v50H0z"/><path stroke="#c3bb86" stroke-width="4" d="M0 299h640M0 320h640"/><path fill="#cfb973" d="M404 78h125v55H404z"/><text x="466" y="102" text-anchor="middle" fill="#33453c" font-size="16">কলকাতা</text><text x="466" y="120" text-anchor="middle" fill="#33453c" font-size="10" font-family="monospace">PLATFORM 03</text>${[150,250,350].map(x=>`<rect x="${x}" y="162" width="72" height="48" rx="8" fill="#e5b936" stroke="#836e2d" stroke-width="3"/><rect x="${x-3}" y="211" width="78" height="14" rx="4" fill="#f2c94c"/><path stroke="#37463d" stroke-width="7" d="M${x+10} 226v27m50-27v27"/>`).join('')}<path stroke="#9ca79a" stroke-width="2" d="M80 63v22m0 20v105"/><ellipse cx="80" cy="88" rx="27" ry="8" fill="#ede0a5"/><text x="18" y="29" fill="#e2dcc1" font-family="monospace" font-size="11">14 NOV  /  02:13</text></svg>`;if(n===1)return `<svg class="photo" role="img" aria-label="A cup of chai beside a handwritten letter on a kitchen table" viewBox="0 0 640 330"><path fill="#887a61" d="M0 0h640v330H0z"/><path fill="#d9cbb0" d="M300 50l220 35-30 215-220-30z"/><path stroke="#9d9681" stroke-width="3" d="M330 100l140 23m-150 10 140 23m-150 10 140 23m-150 10 90 15"/><ellipse fill="#c9bca0" cx="190" cy="190" rx="90" ry="65"/><ellipse fill="#704426" cx="190" cy="178" rx="56" ry="42"/><ellipse fill="none" stroke="#ddca9c" stroke-width="15" cx="190" cy="178" rx="61" ry="47"/><path fill="none" stroke="#dbc69f" stroke-width="15" d="M252 165c58-20 54 61-8 39"/></svg>`;return `<svg class="photo" role="img" aria-label="Rain falling on a window above a Kolkata tram" viewBox="0 0 640 330"><path fill="#5f7e7b" d="M0 0h640v330H0z"/><path fill="#b7b394" d="M110 175h420v110H110z"/><path fill="#425d53" d="M120 195h400v50H120z"/>${[140,215,290,365,440].map(x=>`<path fill="#bac2aa" d="M${x} 200h55v40h-55z"/>`).join('')}<path stroke="#304e49" stroke-width="12" d="M320 0v330M0 135h640"/><path stroke="#b5c7b3" stroke-width="2" d="M60 20l-15 60m140-50-15 60m250-50-15 60m160 100-15 60M70 200l-15 60M230 260l-10 40"/></svg>`}
function content(id){switch(id){case'files':{const folders=['Desktop','Documents','Pictures','Recovered'];let files=folder==='Desktop'?[['locked','IF_YOU_FOUND_THIS.locked','LOCKED'],['notes','call_home.txt','NOTE']]:folder==='Documents'?[['letter','resignation_draft.txt','DRAFT'],['readme','readme.txt','TEXT']]:folder==='Pictures'?[['photos','platform_0213.jpg','PHOTO'],['photos','sunday_chai.jpg','PHOTO'],['photos','last_tram.jpg','PHOTO']]:state.restored?[['log','session_09.log','RESTORED']]:[];return `<div class="file-layout"><nav class="folders">${folders.map(f=>`<button data-folder="${f}" class="${f===folder?'selected':''}">${f==='Recovered'&&state.phase!=='exploration'?'Suppressed testimony':f}</button>`).join('')}</nav><div class="file-list"><div class="crumb">Ari Sen / ${folder}</div>${files.map(([a,n,t])=>`<button class="file-row" data-file="${a}" data-name="${n}">▤ <span>${n}</span><small>${t}</small></button>`).join('')||'<p class="empty">No recovered files yet.<br>Deleted files may still be in Trash.</p>'}</div></div>`}case'notes':return wrap('Notes to myself',`<span class="badge">PINNED / DO NOT SUMMARISE</span><blockquote>When the labels lie, count what remains.</blockquote><p class="sub">MONDAY / BEFORE THE LAST TRAM</p><h3>Small things, first.</h3><p>Tea leaves. Milk. Ginger. The biscuits Ma likes. One working bulb for the kitchen.</p><p>Call Ma before ten. Say I’m eating properly. Actually eat properly.</p><hr class="rule"><div class="reveal-block"><h3>A reminder to myself</h3><p>Mira remembers the call. I remember the platform. If the labels say otherwise, keep the original.</p><button data-open="letter">Open resignation_draft.txt ↗</button></div>${state.scar?'<blockquote>Someone noticed. That happened.</blockquote>':''}`);case'letter':return wrap('An unfinished letter',`<p class="sub">DRAFT · NEVER SENT</p><p>To the PALISADE team,</p><p>I am writing to discuss my workload and the repeated changes to our release schedule. The overnight shifts have become difficult to justify, and my concerns about the review process have not been addressed.</p><p class="reveal-block">That is the version I know you would prefer me to write.</p><p class="reveal-block">What I actually need to say is that the reconstruction is altering testimony. I compared the original records with three successive summaries. These are not compression errors. Each omission protects the same decision.</p><p class="reveal-block">I am no longer willing to sign my name to a memory that has been made convenient. If anything happens to the originals, please ask Mira about the fourth call. I have kept a copy where the system won’t</p><p class="sub">[The draft ends here.]</p>`);case'messages':return wrap('Correspondence',`<p class="sub">ARI ↔ MIRA / FICTIONAL READ-ONLY ARCHIVE</p><div class="message"><small>MIRA · 13 NOV / 21:46</small>Reached home? The rain has swallowed College Street.</div><div class="message ari"><small>ARI · 21:48</small>Still at the office. Save me a chai tomorrow.</div><div class="message"><small>MIRA · 14 NOV / 02:06</small>You called four times. I answered the fourth.</div><div class="message"><small>MIRA · 02:08</small>You told me not to trust the summaries.</div><div class="message"><small>MIRA · 02:11</small>Ari, why does our call history say zero?</div><p class="caption">SYSTEM SUMMARY: No calls took place.</p><button data-action="attachment">▤ Open Ari’s attached note</button><div id="attachment"></div>`);case'photos':return wrap('The contact sheet',`<div class="photo-nav">${['01 / Platform','02 / Sunday','03 / Last tram'].map((p,i)=>`<button data-photo="${i}" aria-pressed="${photo===i}">${p}</button>`).join('')}</div>${scene(photo)}<p class="sub">${['platform_0213.jpg · 14 NOV / 02:13','sunday_chai.jpg · 10 NOV / 09:40','last_tram.jpg · 12 NOV / 19:12'][photo]}</p><p class="caption">${photo===0?'GENERATED CAPTION — MOCK ARCHIVE EXAMPLE<br>“Empty platform. No seating detected.”':photo===1?'Ari’s caption: Sunday chai. Ma’s letter. Nothing urgent.':'Ari’s caption: The last tram, through the rain. I nearly missed it.'}</p>${photo===0?'<button data-action="annotation">✎ Open Ari’s annotation</button><div id="annotation"></div>':'<p class="smallprint">Original local illustration / fictional photograph.</p>'}`);case'audio':return wrap('After the rain',`<span class="badge">RECOVERED TRANSCRIPT / AUDIO UNAVAILABLE</span><p class="sub">voice_memo_0212 · ARI SEN · 00:42</p><blockquote>I’m recording this before I forget which version was mine. Three seats. Four calls. Mira heard me. The station wasn’t empty in the way they say it was. There was somewhere to sit. That sounds like such a small thing to insist on.</blockquote><p>“If the report disappears, don’t look for another report. Look for the things a report would leave out. I need someone who wasn’t here. Someone the reconstruction hasn’t learned to correct.”</p><hr class="rule"><h3>Rain on College Street</h3><p>An unfinished playlist. Chai on the windowsill. A tanpura-like drone, and a few quiet notes.</p><button data-action="sound">♫ Toggle ambient sound</button><p class="smallprint">Original synthesized Indian-inspired ambience, generated locally by your browser. Not a recording or a live music service. Sound is optional.</p>`);case'trash':return wrap('Discarded, not forgotten',state.restored?'<div class="empty">Trash is empty.<br>session_09.log was restored to Files → Recovered.</div><button data-action="recovered">Open Recovered folder ↗</button>':'<p class="sub">1 DELETED FILE / RECOVERABLE</p><h3>session_09.log</h3><p>Deleted: 14 November, 02:13<br>Original location: /system/reconstruction/</p><button class="primary" data-action="restore">Restore file ↗</button><p class="smallprint">Restores this fictional file within the current demo session only.</p>');case'log':return wrap('Session 09',`<span class="badge">RESTORED FROM TRASH</span><pre class="journal">${log}</pre><p class="smallprint">Recovery marker C recorded.</p>`);case'readme':return wrap('Read me',`<p>This computer belongs to Ari Sen.</p><p>If the session comes back without me, start with the ordinary things. Notes. Photographs. A friend who called.</p><p>Keep their order: A, B, C. The final file needs the memories themselves, not just the numbers.</p><p>— A.</p>`);case'terminal':return `<div class="terminal"><p>अ / SEN PERSONAL SYSTEM — TERMINAL</p><pre id="termout">${esc(term.join('\n'))}</pre><form id="terminalform"><label for="command">ari@local:~$</label><input id="command" autocomplete="off" spellcheck="false" aria-label="Simulated terminal command"><button type="submit">↵</button></form><p class="smallprint">Simulation only. No real commands are executed.</p></div>`;case'locked':return wrap('For whoever finds this',`<p class="sub">IF_YOU_FOUND_THIS.locked / RECOVERY SEQUENCE</p><h3>Three memories.<br>Keep their order.</h3><div class="slots">${['A','B','C'].map(k=>`<div class="slot">SLOT ${k}<strong>${state.clues[k]||'—'}</strong>${state.clues[k]?'RECOVERED':'MISSING'}</div>`).join('')}</div>${['reveal','preserved'].includes(state.phase)?'<p>Testimony recovered.</p><button data-open="testimony">Read testimony ↗</button>':'<form id="unlockform" class="codeform"><input name="code" inputmode="numeric" maxlength="3" pattern="[0-9]{3}" aria-label="Three-digit recovery code" placeholder="···" required><button type="submit" class="primary">Recover testimony ↗</button></form><p id="feedback" class="feedback" role="status"></p><button data-action="hint">Need a nudge?</button><p id="hinttext" class="smallprint"></p>'}`);case'help':return wrap('A small field guide',`<p>Explore the icons. A single click opens an app. Read carefully: the originals and their labels don’t always agree.</p><p>Windows can be dragged by their title bars on a wide screen. Use − to minimize; click a taskbar label to restore. On a phone, the taskbar switches between full-screen panels. Escape closes the active window.</p><h3>If you feel lost</h3><p>Three discoveries are needed. Their labels determine the order, not the order in which you find them.</p><button data-action="hint">Show the next hint</button><p id="hinttext" class="caption">Hints are optional.</p><p class="smallprint">All records and consequences are fictional. Progress is saved locally in this browser, separately from Case II.</p>`);case'about':return wrap('Desktop of a Stranger',`<p>A fictional mystery set inside Ari Sen’s recovered computer. Kolkata, 14 November. The clock says 02:13.</p><p>All files, messages, illustrations, and system responses are bundled fictional content. There is no live AI, messaging, data collection, or remote progress saving. Progress is saved only in this browser.</p><p>The optional ambience is synthesized on your device after you turn it on. This experience never reads your real files or identity.</p><p>Created for a frontend workshop · Anshika Rathore</p>`);case'testimony':return wrap('The missing edition',`${testimony}<hr class="rule"><h3>Your path through the reconstruction</h3><p class="smallprint">Actual actions inside this fictional session, in the order you took them.</p><div class="journal">${state.history.map(h=>`${String(h.index).padStart(2,'0')} / ${h.time} / ${esc(h.action)}`).join('\n')}</div><div class="reveal-block"><h3>What remains is your choice.</h3><button class="primary" data-action="preserve">Preserve the testimony ↗</button><p class="smallprint">Keep the evidence available in this browser. Nothing is published or saved remotely; saved in this browser only.</p><button data-open="reset">Reset the reconstruction</button><p class="smallprint">Restart the fictional desktop, leaving one small note.</p></div>`,'PALISADE / RECONSTRUCTION 09');case'reset':return wrap('Begin again?',`<p>This resets the fictional clues and windows in this session. One new note will remain: “Someone noticed. That happened.”</p><button data-action="confirmreset" class="primary">Reset reconstruction</button><button data-action="cancelreset">Keep investigating</button>`);case'replay':return wrap('Replay the mystery?',`<p>Start from the recovered-session screen and clear only Case I’s locally saved progress.</p><button data-action="confirmreplay" class="primary">Start over</button><button data-action="cancelreplay">Cancel</button>`);default:return ''}}
function hints(w){const hints=['Read the pinned note, compare the station photograph with its caption, and open Ari’s annotation.','Mira remembers a call the system denies. Open the attached note in Messages.','Restore session_09.log from Trash. Then read it in Files → Recovered.','Slot A is the seat count. Slot B is the call that connected. Slot C is the restored log marker.','The code is 349. You must still open each piece of evidence.'];w.querySelector('#hinttext').textContent=hints[Math.min(state.hint++,hints.length-1)]}
async function toggleSound(){if(!soundOn){audioCtx??=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();const g=audioCtx.createGain();g.gain.value=.025;g.connect(audioCtx.destination);[130.81,196,261.63,392].forEach((freq,i)=>{const o=audioCtx.createOscillator();o.type='sine';o.frequency.value=freq;const gain=audioCtx.createGain();gain.gain.value=i===0?.6:.15;o.connect(gain);gain.connect(g);o.start();oscillators.push(o)});soundOn=true}else{oscillators.forEach(o=>o.stop());oscillators=[];soundOn=false}$('#sound').textContent=soundOn?'♫ Sound on':'♫ Sound off';$('#sound').setAttribute('aria-pressed',String(soundOn))}
function reset(scar=false,replay=false){for(const w of windows.values())w.remove();windows.clear();state={clues:{},restored:false,history:[],phase:'exploration',hint:0,scar};folder='Desktop';photo=0;term=['SEN terminal / simulated environment','Type help for available commands.'];$('#toast').hidden=true;update();if(replay){$('#desktop').hidden=true;$('#boot').hidden=false;$('#resume').disabled=false;$('#bootstatus').textContent='';$('#resume').focus()}else{open('notes');notify('Reconstruction reset. One note remains.')}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const w=b.closest('.window');if(b.dataset.open){open(b.dataset.open);$('#menupop').hidden=true;$('#menu').setAttribute('aria-expanded','false')}if(b.dataset.task){const t=windows.get(b.dataset.task);t.hidden=false;focusWin(t);tasks()}if(b.dataset.win){const id=w.dataset.app;if(b.dataset.win==='close')close(id);if(b.dataset.win==='min'){w.hidden=true;tasks();$(`[data-task="${id}"]`)?.focus()}if(b.dataset.win==='max')w.classList.toggle('maximized')}if(b.dataset.folder){folder=b.dataset.folder;refresh('files')}if(b.dataset.file){if(b.dataset.file==='photos')photo=['platform_0213.jpg','sunday_chai.jpg','last_tram.jpg'].indexOf(b.dataset.name);open(b.dataset.file);if(b.dataset.file==='photos')refresh('photos')}if(b.dataset.photo){photo=Number(b.dataset.photo);refresh('photos')}switch(b.dataset.action){case'annotation':w.querySelector('#annotation').innerHTML='<blockquote>Recovery slot A = number of yellow seats.</blockquote><p class="smallprint">Fragment A recorded: 3.</p>';clue('A',3);break;case'attachment':w.querySelector('#attachment').innerHTML='<blockquote>Recovery slot B = the call that connected.</blockquote><p class="smallprint">Fragment B recorded: 4.</p>';clue('B',4);break;case'restore':state.restored=true;record('Restored session_09.log');refresh('trash');refresh('files');notify('Restored successfully. Read session_09.log in Files → Recovered.');break;case'recovered':folder='Recovered';open('files');refresh('files');break;case'hint':hints(w);break;case'sound':await toggleSound();break;case'preserve':state.phase='preserved';record('Preserved the testimony');update();notify('Witness record preserved. Evidence remains available for this session.');b.textContent='✓ Witness record preserved';b.disabled=true;break;case'confirmreset':reset(true);break;case'confirmreplay':reset(false,true);break;case'cancelreset':close('reset');break;case'cancelreplay':close('replay');break}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='unlockform'){const code=new FormData(e.target).get('code');const feedback=$('#feedback');if(!canUnlock(state.clues,code)){feedback.textContent=code==='349'?'The numbers match, but memory fragments are still missing. Recover A, B and C first.':'That sequence does not reconnect the memories. Check their labels and try again.';record('Attempted recovery');return}state.phase='recovering';feedback.textContent='Demo recovery loading… Reconnecting memory fragments.';e.target.querySelector('button').disabled=true;record('Unlocked testimony with recovered fragments');setTimeout(()=>{state.phase='reveal';update();refresh('locked');open('testimony');notify('PALISADE / Reconstruction 09 · External witness connected.');},matchMedia('(prefers-reduced-motion: reduce)').matches?50:900)}if(e.target.id==='terminalform'){const input=$('#command'),cmd=input.value.trim();const responses={help:'Commands: help, ls, cat readme.txt, status, clear',ls:'readme.txt  Documents/  Pictures/  Recovered/', 'cat readme.txt':'Trust the originals. A photograph, a call, a discarded log. The final file requires all three memories.',status:`Reconstruction integrity: ${Object.keys(state.clues).length}/3 fragments recovered. Clock sync: 02:13.`};if(cmd==='clear')term=[];else term.push('ari@local:~$ '+cmd,responses[cmd]||'Unknown simulated command. Type help.');refresh('terminal');$('#command').focus()}});
$('#resume').onclick=()=>{$('#resume').disabled=true;$('#bootstatus').textContent='Restoring local session…';setTimeout(()=>{$('#boot').hidden=true;$('#desktop').hidden=false;update();record('Resumed recovered session');$('.desktop-icon').focus()},matchMedia('(prefers-reduced-motion: reduce)').matches?50:800)};$('#sound').onclick=toggleSound;$('#menu').onclick=()=>{$('#menupop').hidden=!$('#menupop').hidden;$('#menu').setAttribute('aria-expanded',String(!$('#menupop').hidden))};$('#replay').onclick=()=>{$('#menupop').hidden=true;open('replay')};document.addEventListener('keydown',e=>{if(e.key==='Escape'){const active=[...windows.entries()].filter(([,w])=>!w.hidden).sort((a,b)=>Number(b[1].style.zIndex)-Number(a[1].style.zIndex))[0];if(active)close(active[0]);$('#menupop').hidden=true}});addEventListener('resize',()=>{for(const w of windows.values()){if(innerWidth>700&&!w.classList.contains('maximized')){const r=w.getBoundingClientRect();w.style.left=`${Math.max(0,Math.min(r.left,innerWidth-r.width))/16}rem`;w.style.top=`${Math.max(42,Math.min(r.top,innerHeight-100))/16}rem`}}});update();
